import urllib.parse, urllib.request, json
q='counterstrain "anterior superior iliac spine" tender point hip flexion external rotation'
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&retmode=json&term='+urllib.parse.quote(q)
try:
 d=json.load(urllib.request.urlopen(u,timeout=15)); ids=d['esearchresult']['idlist']; print('PubMed IDs:',ids)
 if ids:
  v='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?db=pubmed&retmode=json&id='+','.join(ids[:5]); x=json.load(urllib.request.urlopen(v,timeout=15)); print([(i,x['result'][i].get('title')) for i in ids[:5]])
except Exception as e: print(type(e).__name__,str(e))
print('Clinical interpretation: focal lower anterior abdominal tender point near ASIS is consistent with an iliacus/anterior lumbar tender point; classic position is supine with hip flexion and external rotation (often with abduction).')
